mapper.select:
SELECT l.license_id AS licenseId, l.center_code AS centerCode, ISNULL(c.center_name, N'전 센터') AS centerName, l.label AS label, l.issued_by AS issuedBy, l.issued_at AS issuedAt, l.device_limit AS deviceLimit, (SELECT COUNT(*) FROM erp_bookstore_kiosk_device d WHERE d.license_id = l.license_id AND d.revoked_at IS NULL) AS deviceCount FROM erp_bookstore_kiosk_license l LEFT JOIN erp_center c ON c.center_code = l.center_code WHERE l.revoked_at IS NULL
AND l.center_code = #{centerCode}
ORDER BY l.center_code ASC, l.issued_at DESC

mapper.update:
UPDATE erp_bookstore_kiosk_device
SET revoked_at = DATEADD(HOUR, 9, GETUTCDATE()),
    revoked_by = #{revokedBy}
WHERE device_id = #{deviceId}
  AND revoked_at IS NULL

UPDATE erp_bookstore_kiosk_license
SET revoked_at = DATEADD(HOUR, 9, GETUTCDATE()),
    revoked_by = #{revokedBy}
WHERE license_id = #{licenseId}
  AND revoked_at IS NULL
